 elif q.startswith('In which'): k='pack_for_document'; a=re.search(r'(R2-\\d+) \\(CR (\\d+) to TS ([\\d.]+)\\)',q).groups()
 elif q.startswith('Trace'): k='trace'; a=re.search(r'(R2-\\d+) \\(CR (\\d+) to TS ([\\d.]+)\\)',q).groups()
 elif q.startswith('Change request'): k='decision'; a=re.search(r'(R2-\\d+) \\(CR (\\d+) to TS ([\\d.]+)\\)',q).groups()
 else: k='UNKNOWN'; a=q
 g[k].append([x['id'],a,x['fields']])
for k,v in g.items():
 print(k,len(v))
 for x in v: print(json.dumps(x))
